# Важливе зі старого вступу, що переїжджає на початок першого розділу статті.
MOVE = {
 'kino-prosto-neba-u-dvori-terasi': 'Загальний план із обладнанням і правами на фільм ми розібрали в окремому гіді: [[/blog/yak-orhanizuvaty-kinopokaz-prosto-neba/|як організувати кінопоказ просто неба]]. Тут лише про двір, терасу чи дах.',
}

for slug, lead in LEADS.items():
    assert '—' not in lead and '–' not in lead, slug
    p = os.path.join(ROOT, 'blog_src', slug + '.json')
    raw = open(p, encoding='utf-8').read()
    m = re.search(r'\n( +)"', raw); ind = len(m.group(1)) if m else 1   # зберігаємо відступи файлу, щоб diff був лише по суті
    j = json.loads(raw)
    j['lead'] = lead
    if slug in MOVE:
        b = next(b for b in j['blocks'] if b.get('type') == 'text')
        if b.get('cols'):
            col = b['cols'][0]
            if not (col and col[0].get('p') == MOVE[slug]): col.insert(0, {'p': MOVE[slug]})
        else:
            ld = b['lead'] if isinstance(b.get('lead'), list) else ([b['lead']] if b.get('lead') else [])
            if not ld or ld[0] != MOVE[slug]: b['lead'] = [MOVE[slug]] + ld
    open(p, 'w', encoding='utf-8').write(json.dumps(j, ensure_ascii=False, indent=ind) + ('\n' if raw.endswith('\n') else ''))
    print('%4d %s' % (len(lead), slug))
